# VRC Pipeline — Real Experiment Runner
# Hard requirements: real Playwright/Chromium, no smoke mode, no simulation.
# Trials=3, methods=Full+Spark-MU+VP-S+NET-S+VRC-V+VRC-N+VRC-O+VRC, scenarios=nearby+burst_turn+divergent
# Expected: 72 runs (8 methods × 3 scenarios × 3 trials)
#
# Usage: powershell -ExecutionPolicy Bypass -File vrc-paper\run_all.ps1
#
# Environment overrides:
#   $env:VRC_METHODS   = "Full,Spark-MU,VP-S,NET-S,VRC-V,VRC-N,VRC-O,VRC"
#   $env:VRC_SCENARIOS = "nearby,burst_turn,divergent"
#   $env:VRC_TRIALS    = "3"
#   $env:VRC_TRIAL_DURATION_MS = "30000"
#   $env:VRC_HEADLESS  = "true"     # set to "false" to see browser windows

param(
    [string]$Methods       = "",
    [string]$Scenarios     = "",
    [int]   $Trials        = 0,
    [int]   $TrialDuration = 0,
    [string]$Headless      = "",
    [int]   $VitePort      = 0,
    [int]   $SyncPort      = 0
)

# Default: all 8 methods, 3 scenarios, 3 trials — REAL MODE
if (-not $Methods)       { if ($env:VRC_METHODS)            { $Methods       = $env:VRC_METHODS }            else { $Methods       = "Full,Spark-MU,VP-S,NET-S,VRC-V,VRC-N,VRC-O,VRC" } }
if (-not $Scenarios)     { if ($env:VRC_SCENARIOS)          { $Scenarios     = $env:VRC_SCENARIOS }          else { $Scenarios     = "nearby,burst_turn,divergent" } }
if ($Trials -eq 0)       { if ($env:VRC_TRIALS)             { $Trials        = [int]$env:VRC_TRIALS }        else { $Trials        = 3 } }
if ($TrialDuration -eq 0){ if ($env:VRC_TRIAL_DURATION_MS)  { $TrialDuration = [int]$env:VRC_TRIAL_DURATION_MS } else { $TrialDuration = 30000 } }
if (-not $Headless)      { if ($env:VRC_HEADLESS)           { $Headless      = $env:VRC_HEADLESS }           else { $Headless      = "true" } }
if ($VitePort -eq 0)     { if ($env:VITE_PORT)              { $VitePort      = [int]$env:VITE_PORT }         else { $VitePort      = 9200 } }
if ($SyncPort -eq 0)     { if ($env:VRC_SYNC_PORT)          { $SyncPort      = [int]$env:VRC_SYNC_PORT }     else { $SyncPort      = 9201 } }

$ErrorActionPreference = "Continue"
$ScriptDir = Split-Path -Parent $MyInvocation.MyCommand.Path
$RepoRoot  = Split-Path -Parent $ScriptDir
$DebugLog  = Join-Path $ScriptDir "DEBUG_LOG.md"

function Log { param($msg) $ts = Get-Date -Format "HH:mm:ss"; Write-Host "[$ts] $msg" }
function AppendDebug { param($msg) Add-Content $DebugLog "- $msg" }

# ── Setup debug log ──────────────────────────────────────────────────────────
if (-not (Test-Path $DebugLog)) {
    Set-Content $DebugLog "# DEBUG_LOG.md`n`nGenerated by run_all.ps1`n"
}
AppendDebug "run_all.ps1 REAL MODE started at $(Get-Date)"

Log "=== VRC Pipeline: run_all.ps1 [REAL EXPERIMENT MODE] ==="
Log "Repo: $RepoRoot"
Log "Methods: $Methods"
Log "Scenarios: $Scenarios"
Log "Trials: $Trials  Duration: ${TrialDuration}ms  Headless: $Headless"
Log "IMPORTANT: Smoke mode DISABLED. Simulation fallback DISABLED."

$methodCount = ($Methods -split ",").Count
$scenarioCount = ($Scenarios -split ",").Count
$expectedRuns = $methodCount * $scenarioCount * $Trials
Log "Expected runs: $expectedRuns ($methodCount methods × $scenarioCount scenarios × $Trials trials)"

# ── Validate old results are backed up ──────────────────────────────────────
$OldResultsBackup = Join-Path $ScriptDir "results_synthetic_invalid_20260507"
if (Test-Path $OldResultsBackup) {
    Log "Old synthetic results backup confirmed at: $OldResultsBackup"
    AppendDebug "Old invalid synthetic results remain at: $OldResultsBackup (DO NOT USE)"
}

# ── Ensure results/raw is empty from any previous real run ───────────────────
$ResultsRaw = Join-Path $ScriptDir "results\raw"
$existingRaw = Get-ChildItem $ResultsRaw -ErrorAction SilentlyContinue
if ($existingRaw) {
    Log "WARNING: results/raw is not empty — backing up to results_prev_$(Get-Date -Format 'yyyyMMdd_HHmmss')"
    $backup = Join-Path $ScriptDir "results_prev_$(Get-Date -Format 'yyyyMMdd_HHmmss')"
    try {
        Copy-Item (Join-Path $ScriptDir "results") $backup -Recurse -ErrorAction SilentlyContinue
        # Clear only raw and summary for fresh run (keep screenshots of prior run for safety)
        Remove-Item $ResultsRaw -Recurse -Force -ErrorAction SilentlyContinue
        New-Item -ItemType Directory -Force -Path $ResultsRaw | Out-Null
        AppendDebug "Backed up existing results to $backup"
    } catch {
        AppendDebug "WARNING: could not back up results: $_"
    }
}

# ── Check Node.js ─────────────────────────────────────────────────────────────
$nodeExe = $null
$nodeCandidates = @(
    "node",
    "C:\Program Files\nodejs\node.exe",
    "C:\Program Files (x86)\nodejs\node.exe",
    "$env:APPDATA\npm\node.exe",
    "$env:ProgramFiles\nodejs\node.exe"
)
foreach ($nc in $nodeCandidates) {
    try {
        $nv = & $nc --version 2>&1
        if ($nv -match "v\d+\.\d+") { $nodeExe = $nc; Log "Node.js: $nv ($nc)"; break }
    } catch {}
}
if (-not $nodeExe) {
    Log "FATAL: Node.js not found. Install from https://nodejs.org"
    AppendDebug "FATAL: Node.js not found"
    exit 1
}

# ── Check Python ──────────────────────────────────────────────────────────────
$python = $null
$pythonCandidates = @(
    "python3", "python", "py",
    "D:\Download\Anaconda\python.exe",
    "D:\Download\Anaconda3\python.exe",
    "$env:USERPROFILE\Anaconda3\python.exe",
    "$env:USERPROFILE\anaconda3\python.exe",
    "$env:USERPROFILE\安装路径\环境名\python.exe",
    "$env:USERPROFILE\AppData\Local\Programs\Python\Python312\python.exe",
    "$env:USERPROFILE\AppData\Local\Programs\Python\Python311\python.exe",
    "$env:USERPROFILE\AppData\Local\Programs\Python\Python310\python.exe",
    "$env:USERPROFILE\AppData\Local\Programs\Python\Python39\python.exe",
    "C:\Python312\python.exe", "C:\Python311\python.exe",
    "C:\Python310\python.exe", "C:\Python39\python.exe",
    "$env:USERPROFILE\scoop\shims\python3.exe",
    "$env:USERPROFILE\scoop\apps\python\current\python.exe"
)
foreach ($candidate in $pythonCandidates) {
    try {
        $v = & $candidate --version 2>&1
        if ($v -match "Python 3\.\d") {
            $pip = & $candidate -m pip --version 2>&1
            if ($pip -match "pip") { $python = $candidate; break }
        }
    } catch {}
}
if (-not $python) {
    Log "FATAL: Python 3 with pip not found. Analysis requires Python."
    AppendDebug "FATAL: Python not found"
    exit 1
}
Log "Python: $(& $python --version 2>&1) ($python)"
try { & $python -m pip install matplotlib pandas numpy --quiet 2>&1 | Out-Null } catch {}

# ── Kill any existing processes on our ports ──────────────────────────────────
function Kill-Port { param([int]$Port)
    try {
        $pids = netstat -ano 2>$null | Select-String ":$Port " | ForEach-Object {
            ($_ -split "\s+")[-1]
        } | Sort-Object -Unique
        foreach ($pid in $pids) {
            if ($pid -match "^\d+$" -and $pid -ne "0") {
                Stop-Process -Id $pid -Force -ErrorAction SilentlyContinue
                Log "Killed process $pid on port $Port"
                AppendDebug "Killed PID $pid on port $Port"
            }
        }
    } catch {}
}

Log "Clearing ports $VitePort and $SyncPort..."
Kill-Port $VitePort
Kill-Port $SyncPort
Start-Sleep 1

# ── Install server deps ───────────────────────────────────────────────────────
$ServerDir = Join-Path $ScriptDir "server"
Log "Installing sync server deps..."
try {
    Push-Location $ServerDir
    npm install --prefer-offline --silent 2>&1 | Out-Null
    Pop-Location
} catch {
    AppendDebug "npm install in server/ failed: $_"
    try { Pop-Location } catch {}
}

# ── Ensure Spark dist bundle exists ───────────────────────────────────────────
$sparkMin  = Join-Path $RepoRoot "dist\spark.module.min.js"
$sparkDev  = Join-Path $RepoRoot "dist\spark.module.js"
if (-not (Test-Path $sparkMin)) {
    Log "WARNING: spark.module.min.js missing — attempting build"
    try {
        Push-Location $RepoRoot
        npm run build:production 2>&1 | Select-Object -Last 5
        Pop-Location
    } catch { try { Pop-Location } catch {} }
}
if ((-not (Test-Path $sparkDev)) -and (Test-Path $sparkMin)) {
    Log "Copying spark.module.min.js -> spark.module.js"
    try { Copy-Item $sparkMin $sparkDev -ErrorAction Stop } catch {}
}

# ── Install repo deps ─────────────────────────────────────────────────────────
Log "Installing repo deps..."
try {
    Push-Location $RepoRoot
    npm install --prefer-offline --silent 2>&1 | Out-Null
    Pop-Location
} catch { try { Pop-Location } catch {} }

# ── Create required output dirs ───────────────────────────────────────────────
foreach ($d in @("results\raw","results\summary","results\figures","results\screenshots")) {
    New-Item -ItemType Directory -Force -Path (Join-Path $ScriptDir $d) | Out-Null
}

# ── Run experiments (real browser, no smoke, no simulation) ───────────────────
$env:VRC_METHODS            = $Methods
$env:VRC_SCENARIOS          = $Scenarios
$env:VRC_TRIALS             = $Trials
$env:VRC_TRIAL_DURATION_MS  = $TrialDuration
$env:VRC_HEADLESS           = $Headless
$env:VITE_PORT              = $VitePort
$env:VRC_SYNC_PORT          = $SyncPort
# Explicitly disable smoke mode
$env:VRC_SMOKE              = "0"

Log "Running REAL experiment runner (no smoke, no simulation)..."
Log "This will open $expectedRuns browser sessions — expected duration: ~$([math]::Round($expectedRuns * ($TrialDuration / 1000 + 15) / 60, 0)) minutes"

$experimentOk = $false
try {
    Push-Location $RepoRoot
    $exitCode = 0
    & $nodeExe (Join-Path $ScriptDir "experiments\run_experiment.mjs") "--full"
    $exitCode = $LASTEXITCODE
    Pop-Location
    if ($exitCode -eq 0 -or $exitCode -eq $null) {
        $experimentOk = $true
        Log "Experiment runner completed"
    } else {
        Log "Experiment runner exited with code $exitCode"
        AppendDebug "Experiment runner exit code: $exitCode"
    }
} catch {
    AppendDebug "Experiment runner exception: $_"
    Log "WARNING: Experiment runner failed: $_"
    try { Pop-Location } catch {}
}

# Check how many raw files were produced
$rawCount = (Get-ChildItem $ResultsRaw -Filter "*_metrics.jsonl" -ErrorAction SilentlyContinue).Count
Log "Raw metric files produced: $rawCount"

if ($rawCount -eq 0) {
    Log "FATAL: No raw metric files were produced. Real experiment did not generate data."
    Log "Check: Node.js, Playwright, Vite all working?"
    AppendDebug "FATAL: 0 raw metric files after experiment run"
    # Still run analysis to get error reports, but it will exit 1
}

# ── Run analysis (REAL DATA ONLY — no --simulate flag) ────────────────────────
$analysisOk = $false
if ($python) {
    Log "Running analysis on REAL data (--simulate is disabled)..."
    $analyzeScript = Join-Path $ScriptDir "analysis\analyze.py"
    try {
        & $python $analyzeScript
        $analysisExitCode = $LASTEXITCODE
        if ($analysisExitCode -eq 0) {
            $analysisOk = $true
            Log "Analysis complete (Python)"
        } elseif ($analysisExitCode -eq 2) {
            Log "WARNING: Analysis completed with provenance issues (exit 2)"
            $analysisOk = $true
        } else {
            Log "Analysis exited with $analysisExitCode"
            AppendDebug "Analysis exit code: $analysisExitCode"
        }
    } catch {
        AppendDebug "Analysis (Python) failed: $_"
        Log "WARNING: Python analysis failed, falling back to Node.js pipeline..."
    }
}

# ── Node.js analysis fallback (always runs for source_breakdown + canary) ─────
Log "Running Node.js analysis pipeline..."
try {
    & $nodeExe (Join-Path $ScriptDir "analysis\run_analysis.mjs")
    if ($LASTEXITCODE -eq 0 -or $LASTEXITCODE -eq $null) {
        if (-not $analysisOk) { $analysisOk = $true }
        Log "Node.js analysis complete"
    } else {
        Log "Node.js analysis exited with $LASTEXITCODE (canary failures expected)"
        if (-not $analysisOk) { $analysisOk = $true }
    }
} catch {
    AppendDebug "Node.js analysis failed: $_"
    Log "WARNING: Node.js analysis failed: $_"
}

# ── Load pass/fail summary ─────────────────────────────────────────────────────
$pfFile = Join-Path $ScriptDir "results\summary\run_pass_fail.csv"
$passCount = 0; $failCount = 0
if (Test-Path $pfFile) {
    $pfRows = Import-Csv $pfFile
    $passCount = ($pfRows | Where-Object { $_.status -eq "PASS" }).Count
    $failCount  = ($pfRows | Where-Object { $_.status -eq "FAIL" }).Count
    Log "Run pass/fail: $passCount PASS / $failCount FAIL out of $($pfRows.Count) total"
}

# ── Validate required outputs ──────────────────────────────────────────────────
$missing = @()
$required = @(
    "results\figures\fig1_demo_screenshot.png",
    "results\figures\fig3_p95_latency.png",
    "results\figures\fig4_fraction_over_50ms.png",
    "results\figures\fig5_duplicate_ratio.png",
    "results\figures\fig8_ablation.png",
    "results\figures\fig_appendix_all_methods_overview.png",
    "results\summary\metrics_summary.csv",
    "results\summary\per_run_metrics.csv",
    "results\summary\per_client_metrics.csv",
    "results\summary\vrc_decisions.csv",
    "results\summary\run_pass_fail.csv",
    "results\final_report.md",
    "results\provenance_report.json",
    "README.md",
    "RUNBOOK.md",
    "DEBUG_LOG.md"
)
foreach ($f in $required) {
    $fullPath = Join-Path $ScriptDir $f
    if (-not (Test-Path $fullPath)) { $missing += $f }
}

# ── Summary ───────────────────────────────────────────────────────────────────
$figCount = (Get-ChildItem (Join-Path $ScriptDir "results\figures") -Filter "*.png" -ErrorAction SilentlyContinue).Count
$csvCount = (Get-ChildItem (Join-Path $ScriptDir "results\summary") -Filter "*.csv" -ErrorAction SilentlyContinue).Count
$ssCount  = (Get-ChildItem (Join-Path $ScriptDir "results\screenshots") -Filter "*.png" -ErrorAction SilentlyContinue).Count
$rawCount = (Get-ChildItem $ResultsRaw -Filter "*_metrics.jsonl" -ErrorAction SilentlyContinue).Count

Log "=== Pipeline complete ==="
Log "  Raw metric files:  $rawCount  (results\raw\)"
Log "  Figures:           $figCount  (results\figures\)"
Log "  CSVs:              $csvCount  (results\summary\)"
Log "  Screenshots:       $ssCount  (results\screenshots\)"
Log "  Report:            results\final_report.md"
Log "  Runs PASS/FAIL:    $passCount / $failCount"

AppendDebug "run_all.ps1 finished at $(Get-Date) — $rawCount raw, $figCount figures, $csvCount CSVs, $ssCount screenshots"

# ── Provenance report ──────────────────────────────────────────────────────────
$provFile = Join-Path $ScriptDir "results\provenance_report.json"
if (Test-Path $provFile) {
    $prov = Get-Content $provFile | ConvertFrom-Json -ErrorAction SilentlyContinue
    if ($prov) {
        Log "Provenance: ok=$($prov.provenance_ok)  source_files=$($prov.raw_source_files.Count)"
        if (-not $prov.provenance_ok) {
            Log "Provenance ISSUES:"
            foreach ($iss in $prov.issues) { Log "  !! $iss" }
        }
    }
}

if ($missing.Count -gt 0) {
    Log "MISSING required outputs:"
    foreach ($f in $missing) { Log "  MISSING: $f" }
    AppendDebug "Missing outputs: $($missing -join ', ')"
    exit 1
} elseif ($rawCount -eq 0) {
    Log "FAIL: No raw experiment data. Real browser runs did not produce metrics."
    exit 1
} elseif ($failCount -gt 0 -and $passCount -eq 0) {
    Log "FAIL: All runs failed. Check results\raw\errors.jsonl"
    exit 1
} else {
    Log "Pipeline completed ($passCount runs PASS, $failCount FAIL)."
    if ($failCount -gt 0) { Log "WARNING: $failCount runs failed — paper data may be incomplete" }
    exit 0
}
